const payload = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
let source = 'generic';
let eventType = 'unknown';
let service = 'default-service';
let environment = 'production';
let rawLogs = '';

if (headers['x-github-event']) {
  source = 'github';
  eventType = headers['x-github-event'];
  service = payload.repository?.name || 'unknown-repo';
  rawLogs = JSON.stringify(payload);
} else if (payload.schemaId === 'azureMonitorCommonAlertSchema') {
  source = 'azure';
  eventType = payload.data?.essentials?.monitoringService || 'metric_alert';
  service = payload.data?.essentials?.alertTargetIDs?.[0]?.split('/').pop() || 'azure-resource';
  rawLogs = JSON.stringify(payload.data);
} else if (payload.containerId || payload.service) {
  source = 'docker';
  eventType = payload.event || 'container_crash';
  service = payload.service || payload.containerName || 'docker-service';
  rawLogs = payload.logs || JSON.stringify(payload);
} else {
  rawLogs = JSON.stringify(payload);
}

const SENSITIVE_PATTERNS = [
  /bearer\s+[A-Za-z0-9._~+/-]{8,}/gi,
  /(api[_-]?key|token|secret|password|passwd|authorization)\s*[:=]\s*['"]?[^\s,;'"}]+['"]?/gi,
  /-----BEGIN [A-Z ]+ PRIVATE KEY-----[\s\S]*?-----END [A-Z ]+ PRIVATE KEY-----/g,
  /ghp_[A-Za-z0-9]{36}/g,
  /github_pat_[A-Za-z0-9_]{82}/g,
  /DefaultEndpointsProtocol=https;AccountName=[^;]+;AccountKey=[^;]+;/gi
];

let cleanLogs = String(rawLogs);
for (const pattern of SENSITIVE_PATTERNS) {
  cleanLogs = cleanLogs.replace(pattern, (match) => {
    if (match.startsWith('-----BEGIN')) return '[REDACTED_PRIVATE_KEY]';
    if (/^bearer\s+/i.test(match)) return 'Bearer [REDACTED]';
    const idx = match.search(/[:=]/);
    if (idx !== -1) return `${match.slice(0, idx + 1)} [REDACTED]`;
    return '[REDACTED]';
  });
}

const eventId = `evt_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

return [{
  json: {
    eventId,
    timestamp: new Date().toISOString(),
    source,
    eventType,
    service,
    environment,
    sanitizedLogs: cleanLogs.slice(0, 15000),
    clientIp: headers['x-forwarded-for'] || 'internal'
  }
}];
